import 'package:english_words/english_words.dart' as english;

import '../models/word_entry.dart';

class WordDatabase {
  WordDatabase();

  List<WordEntry> getAllWords() {
    final catalog = <String, WordEntry>{for (final entry in words) entry.id: entry};
    for (final raw in english.all) {
      final value = raw.toLowerCase().trim();
      if (value.length < 3 || !RegExp(r'^[a-z]+$').hasMatch(value)) continue;
      catalog.putIfAbsent(value, () => WordEntry(
        word: value.toUpperCase(),
        definition: 'Definition not available in the offline word list.',
        exampleSentence: 'Try using ${value.toUpperCase()} in a sentence of your own.',
        category: 'Vocabulary',
      ));
    }
    return catalog.values.toList(growable: false);
  }

